import java.io.*;import java.util.*;import com.android.tools.smali.dexlib2.*;import com.android.tools.smali.dexlib2.iface.*;import com.android.tools.smali.dexlib2.iface.instruction.*;import com.android.tools.smali.dexlib2.formatter.DexFormatter;
class ScanPeer {public static void main(String[]a)throws Exception{MultiDexContainer<? extends DexFile>d=DexFileFactory.loadDexContainer(new File(a[0]),Opcodes.forApi(37));for(String n:d.getDexEntryNames())for(ClassDef c:d.getEntry(n).getDexFile().getClasses())for(Method m:c.getMethods())if(m.getImplementation()!=null)for(Instruction i:m.getImplementation().getInstructions())if(i instanceof ReferenceInstruction){String r=DexFormatter.INSTANCE.getReference(((ReferenceInstruction)i).getReference());if(r.contains("WebViewPageBoundaryInterface")||r.contains("IsomorphicObjectBoundaryInterface;->getOrCreatePeer")||r.contains("WebViewNavigationBoundaryInterface"))System.out.println(DexFormatter.INSTANCE.getMethodDescriptor(m)+" => "+r);}}}
